    /// Enter while the agent works: text becomes steering; read-only commands that are safe during a turn run;
    /// anything else stays in the draft with an explanation.
    fn submit_while_busy(&mut self, display: String, invocation: Option<Invocation>) -> Option<Action> {
        match invocation {
            None => {}
            Some(Invocation::Help) => {
                self.composer.take();
                self.overlay = Some(Overlay::Help { scroll: 0 });
                return None;
            }
            Some(Invocation::Receipt) => {
                self.composer.take();
                return self.open_receipt();
            }
            Some(Invocation::Details) => {
                self.composer.take();
                self.show_details();
                return None;
            }
            Some(Invocation::Quit) => return Some(Action::Quit),
            Some(Invocation::Remote { command, args }) if command == "doctor" && !args.split_whitespace().any(|a| a == "--fix") => {
                self.composer.take();
                self.slash_seq += 1;
                let id = format!("s{}", self.slash_seq);
                self.transcript.push(Entry::Command(display));
                return Some(Action::Send(Command::Slash { id, command, args }));
            }
            Some(_) => {
                self.transcript.push(Entry::Notice(
                    "Commands run when the agent is idle (esc cancels the turn). Text without a leading / is sent as steering.".into(),
                ));
                return None;
            }
        }
        let text = self.composer.take();
        self.scroll_back = 0;
        self.focus = Focus::Composer;
        self.steer_seq += 1;
        let id = format!("g{}{}", steer_prefix(), self.steer_seq);
        self.steer_texts.insert(id.clone(), text.clone());
        self.transcript.push(Entry::Steer {
            id: id.clone(),
            text: display,
            state: SteerState::Sending,
            message: String::new(),
        });
        Some(Action::Send(Command::Steer { id, text }))
    }

    /// A status row for `key`: the one this turn already shows is updated in place, otherwise a new row starts.
    /// The search stops at the operator's prompt, so a later turn's wait never rewrites an earlier turn's row.
    fn put_status(&mut self, key: String, text: String) {
        for entry in self.transcript.iter_mut().rev() {
            match entry {
                Entry::Status { key: k, text: t } if *k == key => {
                    base
                };
                Line::from(Span::styled(format!("  {}", expand_tabs(row)), style))
            }));
        }
        Entry::Info(text) | Entry::Status { text, .. } => lines.push(Line::from(Span::styled(
            format!("  · {}", one_line(text)),
            muted,
        ))),
        Entry::Steer {
            text,
            state,
            message,
            ..
        } => {
            let (label, color) = match state {
                SteerState::Sending => ("sending", ACCENT),
                SteerState::Queued => ("queued for the next step", ACCENT),
                SteerState::Applied => ("applied", Color::Green),
                SteerState::Deferred => ("starts a follow-up turn", ACCENT),
                SteerState::Cancelled => ("not applied", Color::Yellow),
                SteerState::Rejected => ("not applied", Color::Yellow),
                SteerState::Duplicate => ("already received", MUTED),
                SteerState::Lost => ("not delivered", Color::Red),
            };
            lines.push(Line::default());
            for (index, row) in text.split('\n').enumerate() {
                lines.push(Line::from(vec![
                    Span::styled(if index == 0 { "↳ " } else { "  " }, prompt),
                    Span::styled(expand_tabs(row), white),
                ]));
            }
            let mut status = vec![Span::styled(format!("  steering · {label}"), Style::default().fg(color))];
            if !message.is_empty() && !matches!(state, SteerState::Queued | SteerState::Applied) {
                status.push(Span::styled(format!(" — {}", one_line(message)), muted));
            }
            lines.push(Line::from(status));
        }
    }
    if ctx.first && lines.first().is_some_and(|line| line.spans.is_empty()) {
        lines.remove(0);
    }
    if ctx.selected {
        lines = lines.into_iter().map(|line| line.patch_style(highlight)).collect();
    }
    lines
}

